// Settings > About > Third-party licenses: THIRD_PARTY_NOTICES.md (generated by
// `pnpm notices`) as plain text. Lazy: the text only loads when the dialog opens.
import notices from '../../../../THIRD_PARTY_NOTICES.md?raw';
import { Button } from '../../../shared/ui/Button';
import { Dialog } from '../../../shared/ui/Dialog';
import { t } from '../../i18n';

export default function LicensesDialog(props: { onClose: () => void }) {
  return (
    <Dialog
      open
      title={t('settings.about.licenses')}
      class="af-licenses"
      onClose={() => props.onClose()}
      actions={<Button onClick={() => props.onClose()}>{t('dialog.close')}</Button>}
    >
      <pre class="af-licenses-text" tabindex="0">
        {notices}
      </pre>
    </Dialog>
  );
}
